(assert (= "1.12.6" (clojure-version)))
(defn f1 [x] x)
(defn box-reuse-double-raw [f n] (let [n (long n) x (+ 1.25 0.5)] (loop [i 0 c 0] (if (< i n) (let [r (f x)] (recur (inc i) (if (== (double r) (double x)) (inc c) c))) c))))
(defn box-reuse-double-boxed [f n] (let [n (long n) x (identity 1.75)] (loop [i 0 c 0] (if (< i n) (let [r (f x)] (recur (inc i) (if (== (double r) (double x)) (inc c) c))) c))))
(defn box-reuse-long-raw [f n] (let [n (long n) x (+ 3000000000 5)] (loop [i 0 c 0] (if (< i n) (let [r (f x)] (recur (inc i) (if (== (long r) (long x)) (inc c) c))) c))))
(defn box-reuse-long-boxed [f n] (let [n (long n) x (identity 3000000005)] (loop [i 0 c 0] (if (< i n) (let [r (f x)] (recur (inc i) (if (== (long r) (long x)) (inc c) c))) c))))
(doseq [n [0 1 7 33]] (let [actual (box-reuse-double-raw f1 n)] (prn "double-raw" n actual) (assert (= n actual))))
(doseq [n [0 1 7 33]] (let [actual (box-reuse-double-boxed f1 n)] (prn "double-boxed" n actual) (assert (= n actual))))
(doseq [n [0 1 7 33]] (let [actual (box-reuse-long-raw f1 n)] (prn "long-raw" n actual) (assert (= n actual))))
(doseq [n [0 1 7 33]] (let [actual (box-reuse-long-boxed f1 n)] (prn "long-boxed" n actual) (assert (= n actual))))
